components/themevale/homepage/component/:
{{#each categories}}
    {{#if id '==' ../category_id}}
        <div class="themevale_productsByCategoryId layout-3">
            <div class="themevale_page-heading-wrapper">
                <h2 class="page-heading"><a href="{{url}}">{{../../theme_settings.carousel-category-id-2-title}}</a></h2>
            </div>
            <div class="themevale-content" data-themevale-products-by-category="{{url}}">
                {{> components/themevale/homepage/component/product-loading theme_settings=../../theme_settings}}
            </div>
        </div>
    {{else}}
        {{#each children}}
            {{#if id '==' ../../../category_id}}
                <div class="themevale_productsByCategoryId layout-3">
                    <div class="themevale_page-heading-wrapper">
                        <h2 class="page-heading"><a href="{{url}}">Recommendations for you</a></h2>
                    </div>
                    <div class="themevale-content" data-themevale-products-by-category="{{url}}">
                        {{> components/themevale/homepage/component/product-loading theme_settings=../../../../theme_settings}}
                    </div>
                </div>
            {{else}}
                {{#each children}}
                    {{#if id '==' ../../../../../category_id}}
                        <div class="themevale_productsByCategoryId layout-3">
                            <div class="themevale_page-heading-wrapper">
                                <h2 class="page-heading"><a href="{{url}}">Recommendations for you</a></h2>
                            </div>
                            <div class="themevale-content" data-themevale-products-by-category="{{url}}">
                                {{> components/themevale/homepage/component/product-loading theme_settings=../../../../../../theme_settings}}
                            </div>
                        </div>
                    {{/if}}
                {{/each}}
            {{/if}}
        {{/each}}
    {{/if}}
{{/each}}
